    const menuData = {
      health: ["Breast Cancer", "Chronic Kidney Disease", "COPD", "Digestive Health", "Eye Health", "Heart Health", "Menopause", "Mental Health", "Migraine", "Multiple Sclerosis", "Parkinson's Disease", "Psoriasis", "Rheumatoid Arthritis", "Sleep Health", "Type 2 Diabetes", "Weight Management"],
      wellness: ["Nutrition", "Fitness", "Mental Well-Being", "Sleep", "Preventive Care", "Healthy Aging"],
      tools: ["Recipe Hub", "Macronutrient Calculator", "Calorie Calculator", "Drug Directory", "Pill Identifier", "FindCare"],
      featured: ["Trending", "Editor's Picks", "Expert Interviews", "Seasonal Health", "Most Shared"],
      connect: ["Newsletter", "Community Stories", "Ask the Expert", "About WellSource", "Contact"]
    };

    const megaMenu = document.getElementById('mega-menu');
    const navButtons = document.querySelectorAll('.nav-btn');

    navButtons.forEach(btn => {
      btn.addEventListener('click', () => {
        const menu = btn.dataset.menu;
        const open = btn.getAttribute('aria-expanded') === 'true';
        navButtons.forEach(b => b.setAttribute('aria-expanded', 'false'));

        if (open) {
          megaMenu.classList.remove('open');
          megaMenu.innerHTML = '';
          return;
        }

        btn.setAttribute('aria-expanded', 'true');
        megaMenu.innerHTML = `
          <div class="mega-grid">
            ${menuData[menu].map(item => `<a href="index.html" class="mega-link">${item}</a>`).join('')}
          </div>
        `;
        megaMenu.classList.add('open');
      });
    });

    document.addEventListener('click', (e) => {
      if (!e.target.closest('.main-nav')) {
        navButtons.forEach(b => b.setAttribute('aria-expanded', 'false'));
        megaMenu.classList.remove('open');
      }
    });

    const readsData = {
      top: [
        ["Nutrition", "16 Superfoods That Are Worthy of the Title"],
        ["Weight Loss", "Does Ozempic Cause Hair Loss?"],
        ["Mental Well-Being", "Can Music Therapy Help with Depression?"],
        ["Apps", "These Are the 8 Best Calorie Counter Apps"]
      ],
      fitness: [
        ["Training", "How to Build a Beginner Strength Routine"],
        ["Cardio", "Zone 2 Workouts: Why Everyone Is Talking About Them"],
        ["Recovery", "Foam Rolling: What It Helps and What It Doesn't"],
        ["Mobility", "Five Daily Stretches for Desk Workers"]
      ],
      mental: [
        ["Stress", "10-Minute Habits That Lower Daily Stress"],
        ["Sleep", "How Anxiety Impacts Sleep Quality"],
        ["Therapy", "How to Choose the Right Therapist for You"],
        ["Mindfulness", "Breathing Exercises You Can Do Anywhere"]
      ],
      reviews: [
        ["Wearables", "Best Smart Rings for Sleep Tracking in 2026"],
        ["Kitchen", "Are Air Fryers Actually Healthier?"],
        ["Office", "Is Floor Sitting the New Standing?"],
        ["Shoes", "Supportive Walking Shoes Dermatologists Recommend"]
      ],
      recipes: [
        ["Heart Health", "7 Low-Sodium Dinners That Still Taste Great"],
        ["Diabetes", "Balanced Breakfasts for Stable Blood Sugar"],
        ["Quick Meals", "15-Minute High-Protein Lunches"],
        ["Family", "Kid-Friendly Meals with Hidden Vegetables"]
      ],
      skin: [
        ["Dermatology", "Do You Really Need a Separate Night Cream?"],
        ["Ingredients", "Niacinamide vs Vitamin C: Which First?"],
        ["Sun Safety", "How Much Sunscreen Is Enough?"],
        ["Acne", "Gentle Routines for Adult Acne"]
      ]
    };

    const tabs = document.querySelectorAll('.tab');
    const readsGrid = document.getElementById('reads-grid');

    function renderReads(tabKey) {
      readsGrid.innerHTML = readsData[tabKey].map(([cat, title]) => `
        <article class="tile">
          <div class="kicker" style="margin-bottom: .3rem;">${cat}</div>
          <h3 style="margin: 0; font-size: 1.05rem;">${title}</h3>
        </article>
      `).join('');
    }
    renderReads('top');

    tabs.forEach(tab => {
      tab.addEventListener('click', () => {
        tabs.forEach(t => t.classList.remove('active'));
        tab.classList.add('active');
        renderReads(tab.dataset.tab);
      });
    });

    const topicRow = document.getElementById('topics-row');
    document.getElementById('topics-prev').addEventListener('click', () => {
      topicRow.scrollBy({ left: -320, behavior: 'smooth' });
    });
    document.getElementById('topics-next').addEventListener('click', () => {
      topicRow.scrollBy({ left: 320, behavior: 'smooth' });
    });

    const newsletter = document.getElementById('newsletter-form');
    newsletter.addEventListener('submit', (e) => {
      e.preventDefault();
      const email = document.getElementById('email').value.trim();
      if (!email) return;
      alert(`Thanks for joining WellSource, ${email}!`);
      newsletter.reset();
    });
  </script>
</body>
