    const readsGrid = document.getElementById('reads-grid');

    function renderReads(tabKey) {
      readsGrid.innerHTML = readsData[tabKey].map(([cat, title]) => `
        <article class="tile">
          <div class="kicker" style="margin-bottom: .3rem;">${cat}</div>
          <h3 style="margin: 0; font-size: 1.05rem;">${title}</h3>
        </article>
      `).join('');
    }
    renderReads('top');

    tabs.forEach(tab => {
      tab.addEventListener('click', () => {
        tabs.forEach(t => t.classList.remove('active'));
        tab.classList.add('active');
        renderReads(tab.dataset.tab);
      });
    });

    const topicRow = document.getElementById('topics-row');
    document.getElementById('topics-prev').addEventListener('click', () => {
      topicRow.scrollBy({ left: -320, behavior: 'smooth' });
    });
    document.getElementById('topics-next').addEventListener('click', () => {
      topicRow.scrollBy({ left: 320, behavior: 'smooth' });
    });

    const newsletter = document.getElementById('newsletter-form');
    newsletter.addEventListener('submit', (e) => {
      e.preventDefault();
      const email = document.getElementById('email').value.trim();
      if (!email) return;
      alert(`Thanks for joining WellSource, ${email}!`);
      newsletter.reset();
    });
  </script>
